// SwiftUI
struct PasswordField: View {
    @State private var pw = ""

    var body: some View {
        JdPasswordInput(text: $pw,
                        placeholder: "비밀번호",
                        showsStrength: true,        // 강도 막대 + 라벨(취약/보통/양호/강력)
                        showsRules: true,           // 규칙 체크리스트
                        accessibilityLabel: "비밀번호")
    }
}

